package cn.xigua.childcare;
import android.app.*;
import android.text.*;
import android.widget.*;
import org.json.*;
import java.util.*;

/** Capability-first model settings. Each role keeps its own service and model binding. */
final class AiSettings {
 private final Activity a;private final CareApp app;private final Ui u;private final Providers providers;
 private static final String[] ROLES={"chat","asr","tts","vision","judge"};
 AiSettings(Activity a,CareApp app,Ui u){this.a=a;this.app=app;this.u=u;providers=new Providers(a,app.store);}
 void render(LinearLayout body){u.add(body,u.label("每一种能力都可以使用不同的地址、Key 和模型；修改一项不会覆盖其他能力。"),8);for(String role:ROLES){JSONObject p=providers.get(providers.selected(role));String model=p==null?"未选择":p.optString(Providers.modelKey(role),"未选择");String name=p==null?"尚未配置":p.optString("name");if("tts".equals(role)&&"system".equals(model)){name="手机系统语音";model="系统 TTS";}final String r=role;u.item(body,Providers.roleLabel(role),name+" · "+model,"配置",()->roleDetail(r));}u.section(body,"已保存的服务","同一套服务可以明确分配给多个角色，也可以分别填写不同地址。");u.add(body,u.button("添加一套服务",true,()->edit(null)),12);JSONArray list=providers.all();for(int i=0;i<list.length();i++){JSONObject p=list.optJSONObject(i);if(p!=null)serviceRow(body,p);}}
 private void serviceRow(LinearLayout body,JSONObject p){String id=p.optString("id");LinearLayout row=u.row();row.setMinimumHeight(u.dp(64));row.setPadding(u.dp(12),u.dp(6),u.dp(8),u.dp(6));row.setBackground(u.shape(u.surface,12));LinearLayout labels=u.column();labels.addView(u.text(p.optString("name"),16,u.ink,true));labels.addView(u.text(p.optString("key").isEmpty()?"未填写 Key":"Key 已保存",12,u.muted,false));row.addView(labels,new LinearLayout.LayoutParams(0,-2,1));TextView edit=u.button("编辑",false,()->edit(p));row.addView(edit);row.setContentDescription(p.optString("name")+"，服务配置");u.add(body,row,6);}
 private void roleDetail(String role){JSONObject selected=providers.get(providers.selected(role));LinearLayout fields=u.column();fields.setPadding(u.dp(16),u.dp(8),u.dp(16),u.dp(8));u.add(fields,u.text(Providers.roleLabel(role),20,u.ink,true),0);u.add(fields,u.label("独立选择服务、模型和适配方式；保存后才会用于新的请求。"),8);Spinner service=new Spinner(a);JSONArray list=providers.all();List<String> labels=new ArrayList<>();List<String> ids=new ArrayList<>();for(int i=0;i<list.length();i++){JSONObject p=list.optJSONObject(i);if(p!=null){ids.add(p.optString("id"));labels.add(p.optString("name"));}}service.setAdapter(new ArrayAdapter<String>(a,android.R.layout.simple_spinner_dropdown_item,labels));for(int i=0;i<ids.size();i++)if(ids.get(i).equals(providers.selected(role)))service.setSelection(i);u.add(fields,u.label("服务配置"),12);u.add(fields,service,4);String current=selected==null?"":selected.optString(Providers.modelKey(role));EditText model=u.input("模型 ID（可手填）","system".equals(current)?"system":current,1);model.setFilters(new InputFilter[]{new InputFilter.LengthFilter(200)});u.add(fields,u.label("模型 ID"),10);u.add(fields,model,4);if("tts".equals(role))u.add(fields,u.label("填写 system 使用手机系统 TTS；远程 TTS 需要服务提供兼容语音接口。"),8);if("vision".equals(role))u.add(fields,u.label("视觉模型只保存独立配置；实际图片输入能力以服务接口测试结果为准。"),8);if("judge".equals(role))u.add(fields,u.label("JEV 判断模型只负责意图判断与分流，不会自动保存照护记录。"),8);new AlertDialog.Builder(a).setTitle("配置"+Providers.roleLabel(role)).setView(fields).setPositiveButton("保存",(d,w)->{try{int n=service.getSelectedItemPosition();if(n<0||n>=ids.size())throw new IllegalArgumentException("请先添加服务");JSONObject p=providers.get(ids.get(n));p.put(Providers.modelKey(role),model.getText().toString().trim());providers.save(p);providers.select(role,p.optString("id"));app.changed();toast("已保存"+Providers.roleLabel(role)+"配置");}catch(Exception e){toast(e.getMessage());}}).setNegativeButton("取消",null).setNeutralButton("获取模型",(d,w)->{if(selected!=null)fetch(selected);}).show();}
 private void fetch(JSONObject p){String id=p.optString("id");long revision=p.optLong("revision");if(p.optString("key").isEmpty()){toast("请先填写这套服务的 Key");return;}toast("正在读取该服务的模型列表");app.network.execute(()->{JSONArray models=new JSONArray();String status;try{models=new MimoClient(p).models();status="已获取 "+models.length()+" 个模型；可分别分配给五种能力";}catch(Exception e){status=e.getMessage()==null?"模型列表不可用，仍可手填模型 ID":e.getMessage();}boolean saved=providers.models(id,revision,models,status);app.changed();String message=saved?"模型列表已更新："+status:"配置已变化，请重新获取";app.main.post(()->toast(message));});}
 private EditText field(LinearLayout body,String label,String initial,int type,int limit){u.add(body,u.label(label),10);EditText input=u.input(label,initial,type);input.setFilters(new InputFilter[]{new InputFilter.LengthFilter(limit)});u.add(body,input,4);return input;}
 private void edit(JSONObject previous){JSONObject p=previous==null?Store.obj("id","","revision",0,"name","","base","https://","key","","chat_model","","asr_model","","tts_model","system","vision_model","","judge_model","","auth","bearer","asr_protocol","transcriptions"):Store.json(previous.toString());LinearLayout fields=u.column();fields.setPadding(u.dp(16),u.dp(8),u.dp(16),u.dp(12));EditText name=field(fields,"服务名称",p.optString("name"),1,40),base=field(fields,"HTTPS Base URL",p.optString("base"),InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_URI,2048),key=field(fields,"API Key",p.optString("key"),InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD,4096);u.add(fields,u.label("五种能力的模型 ID（不填表示该服务不承担此角色）"),10);EditText chat=field(fields,"文字推理模型",p.optString("chat_model"),1,200),asr=field(fields,"ASR 语音识别模型",p.optString("asr_model"),1,200),tts=field(fields,"TTS 语音合成模型（system 表示手机）",p.optString("tts_model","system"),1,200),vision=field(fields,"视觉理解模型",p.optString("vision_model"),1,200),judge=field(fields,"JEV 判断模型",p.optString("judge_model"),1,200);Spinner auth=new Spinner(a);auth.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,new String[]{"Bearer Token","API-Key"}));auth.setSelection("api-key".equals(p.optString("auth"))?1:0);u.add(fields,u.label("鉴权方式"),8);u.add(fields,auth,4);Spinner protocol=new Spinner(a);protocol.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,new String[]{"MiMo 音频消息接口","兼容音频转写接口"}));protocol.setSelection("transcriptions".equals(p.optString("asr_protocol"))?1:0);u.add(fields,u.label("ASR 接口"),8);u.add(fields,protocol,4);ScrollView wrap=new ScrollView(a);wrap.addView(fields);AlertDialog dialog=new AlertDialog.Builder(a).setTitle(previous==null?"添加服务":"编辑服务").setView(wrap).setPositiveButton("保存",null).setNegativeButton("取消",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{try{JSONObject value=Store.json(p.toString());String url=base.getText().toString().trim().replaceAll("/+$","");value.put("name",name.getText().toString().trim());value.put("base",url);value.put("key",key.getText().toString().trim());value.put("chat_model",chat.getText().toString().trim());value.put("asr_model",asr.getText().toString().trim());value.put("tts_model",tts.getText().toString().trim());value.put("vision_model",vision.getText().toString().trim());value.put("judge_model",judge.getText().toString().trim());value.put("auth",auth.getSelectedItemPosition()==1?"api-key":"bearer");value.put("asr_protocol",protocol.getSelectedItemPosition()==0?"mimo":"transcriptions");ProviderRules.validate(value.optString("name"),url,value.optString("key"),value.optString("chat_model"),value.optString("asr_model"),value.optString("auth"));if(!url.equals(p.optString("base"))||!value.optString("key").equals(p.optString("key"))){value.remove("models");value.remove("models_status");}providers.save(value);dialog.dismiss();app.changed();toast("服务配置已保存");}catch(Exception e){toast(e.getMessage());}}));dialog.show();}
 private void toast(String message){Toast.makeText(a,message==null?"操作未完成，请重试":message,Toast.LENGTH_LONG).show();}
}
